using System;using System.Linq;using Newtonsoft.Json.Linq;using UnityEngine;using UnityEngine.Rendering;
namespace MotionStudio {
 public class NativeStage {
  public Transform root;public NativeStage(string url){var doc=JObject.Parse(System.IO.File.ReadAllText(NativeAssets.Local(url)));root=new GameObject("Native Stage").transform;var nodes=NativeAssets.Nodes((JArray)doc["nodes"],root);foreach(JObject d in doc["meshes"]){if((bool?)d["enabled"]==false)continue;var obj=new GameObject((string)d["name"]);obj.transform.SetParent(nodes[(int)d["node"]],false);obj.AddComponent<MeshFilter>().sharedMesh=NativeAssets.Mesh(d,nodes);var renderer=obj.AddComponent<MeshRenderer>();renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.sharedMaterials=d["materials"].Cast<JObject>().Select(m=>{bool transparent=(bool?)m["transparent"]==true||(bool?)m["additive"]==true;var material=new Material(Shader.Find(transparent?"22-7 Native/StageSurface":"Unlit/Texture"));if(transparent){var color=m["color"];material.color=new Color((float)color[0],(float)color[1],(float)color[2],(float?)m["opacity"]??1);material.SetFloat("_Cull",(bool?)m["doubleSide"]==true?0:2);material.SetFloat("_DstBlend",(bool?)m["additive"]==true?1:10);}material.mainTexture=NativeAssets.Texture((string)m["texture"]);var repeat=m["repeat"];if(repeat!=null)material.mainTextureScale=new Vector2((float)repeat[0],(float)repeat[1]);var offset=m["offset"];if(offset!=null)material.mainTextureOffset=new Vector2((float)offset[0],(float)offset[1]);return material;}).ToArray();}
   foreach(JObject item in doc["lights"].OrderByDescending(l=>(float?)l["intensity"]??0).Take(12)){if((bool?)item["enabled"]==false)continue;var node=nodes[(int)item["node"]];var light=node.gameObject.AddComponent<Light>();light.type=(int)item["type"]==2?LightType.Spot:LightType.Point;var c=item["color"];light.color=new Color((float)c[0],(float)c[1],(float)c[2]);light.intensity=((float?)item["intensity"]??1)*.3f;light.range=(float?)item["range"]??8;light.spotAngle=(float?)item["angle"]??45;light.renderMode=LightRenderMode.ForcePixel;light.shadows=LightShadows.None;}
  }public void Dispose(){UnityEngine.Object.Destroy(root.gameObject);}
 }
}
